// Helper functions
export function getSurahNames() {
  return surahIndex.map(s => ({
    no: s.no,
    name_en: s.name_en,
    name_ar: s.name_ar,
    name_roman: s.name_roman,
    verse_count: s.verse_count,
    place: s.place
  }));
}

export function getVersesBySurah(surahNo) {
  return quranData.verses.filter(v => v.s === surahNo);
}

export function getVersesByTopic(topicName) {
  return quranData.verses.filter(v => v.t === topicName);
}

export function getVerseById(id) {
  return quranData.verses.find(v => v.id === id);
}

export function getVersesByJuz(juzNo) {
  return quranData.verses.filter(v => v.j === juzNo);
}

export function getTopics() {
  return topicIndex.map(t => t.name);
}

export function searchVerses(query) {
  const q = query.toLowerCase();
  return quranData.verses.filter(v =>
    v.ar.includes(query) ||
    v.ep.toLowerCase().includes(q) ||
    v.ey.toLowerCase().includes(q)
  );
}

export function getRandomVerse() {
  return quranData.verses[Math.floor(Math.random() * quranData.verses.length)];
}

export function getVerseContext(verse) {
  const surah = surahIndex.find(s => s.no === verse.s);
  return {
    surah: surah,
    verse: verse,
    prevVerse: verse.id > 1 ? getVerseById(verse.id - 1) : null,
    nextVerse: verse.id < quranData.verses.length ? getVerseById(verse.id + 1) : null,
  };
}
